assets/theme.css:
/* Bloom — EcomStrait Liquid theme. Colors/fonts/radius come from theme settings;
   pastel washes are mixed from the merchant's brand + accent. */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--font-body);color:var(--ink);background:var(--bg);line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block;object-fit:cover}
a{color:inherit;text-decoration:none}
h1,h2,h3{font-family:var(--font-heading);line-height:1.15;margin:0;font-weight:700}
.muted{color:var(--muted)}
.container{width:100%;max-width:1200px;margin:0 auto;padding:0 20px}
.section{padding:64px 0}
.section--narrow{max-width:760px;margin:0 auto}
.section-title{font-size:clamp(1.7rem,3.2vw,2.4rem);letter-spacing:-.02em}
.section-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:28px}
.link-more{color:var(--brand);font-weight:700;font-size:.92rem;white-space:nowrap}
.link-more:hover{color:var(--accent)}

/* Buttons — chunky pills */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;border:2px solid transparent;cursor:pointer;font-family:var(--font-body);font-weight:700;font-size:.95rem;padding:.8rem 1.6rem;border-radius:999px;transition:transform .18s cubic-bezier(.34,1.56,.64,1),box-shadow .18s ease,background-color .2s ease}
.btn-lg{padding:1rem 2.1rem;font-size:1.02rem}
.btn-primary{background:var(--brand);color:#fff;box-shadow:0 6px 0 color-mix(in srgb,var(--brand) 62%,#000)}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 8px 0 color-mix(in srgb,var(--brand) 62%,#000)}
.btn-primary:active{transform:translateY(4px);box-shadow:0 2px 0 color-mix(in srgb,var(--brand) 62%,#000)}
.btn-primary[disabled]{background:var(--muted);box-shadow:none;cursor:not-allowed;transform:none}
.btn-ghost{background:var(--bg);border-color:var(--line);color:var(--ink)}
.btn-ghost:hover{border-color:var(--brand);color:var(--brand)}

/* Header */
.site-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(10px);border-bottom:2px solid var(--wash)}
.site-header__inner{display:flex;align-items:center;justify-content:space-between;gap:24px;height:70px}
.site-header__name{font-family:var(--font-heading);font-weight:700;font-size:1.3rem;letter-spacing:-.02em;color:var(--brand)}
.site-nav{display:flex;gap:10px}
.site-nav__link{font-size:.93rem;font-weight:600;color:var(--muted);padding:8px 14px;border-radius:999px;transition:background-color .2s ease,color .2s ease}
.site-nav__link:hover,.site-nav__link.is-active{color:var(--ink);background:var(--wash)}
.site-header__cart{font-weight:700;font-size:.92rem;display:inline-flex;align-items:center;gap:8px}
.cart-count{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 7px;border-radius:999px;background:var(--brand);color:#fff;font-size:.74rem}
@media (max-width:640px){.site-nav{display:none}.site-header__inner{height:62px}}

/* Hero — soft gradient with floating blobs */
.hero{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--wash),var(--wash-2));background-size:cover;background-position:center}
.hero__inner{position:relative;z-index:1;padding:104px 20px;text-align:center;max-width:780px;margin:0 auto}
.hero__heading{font-size:clamp(2.1rem,5.4vw,3.6rem);letter-spacing:-.03em}
.hero__subheading{font-size:clamp(1rem,2vw,1.18rem);color:var(--muted);margin:18px auto 32px;max-width:52ch}
.hero--image .hero__inner{padding:136px 20px}
.hero__blob{position:absolute;border-radius:50%;filter:blur(56px);opacity:.5;pointer-events:none}
.hero__blob--a{width:340px;height:340px;background:var(--brand);top:-110px;left:-80px}
.hero__blob--b{width:300px;height:300px;background:var(--accent);bottom:-120px;right:-70px}
.hero--image .hero__blob{display:none}
@media (max-width:640px){.hero__inner,.hero--image .hero__inner{padding:72px 20px}.hero__blob{display:none}}

/* Grids */
.grid{display:grid;gap:22px}
.grid-products{grid-template-columns:repeat(2,1fr)}
.grid-collections{grid-template-columns:repeat(2,1fr)}
.grid-3{grid-template-columns:repeat(3,1fr)}
@media (min-width:720px){.grid-products{grid-template-columns:repeat(4,1fr)}.grid-collections{grid-template-columns:repeat(3,1fr)}}
@media (max-width:640px){.grid-3{grid-template-columns:1fr}}

/* Product card */
.product-card{display:flex;flex-direction:column;overflow:hidden;background:var(--bg);border:2px solid var(--wash);transition:transform .2s cubic-bezier(.34,1.56,.64,1),box-shadow .2s ease,border-color .2s ease}
.product-card:hover{transform:translateY(-4px);border-color:var(--brand);box-shadow:0 14px 30px color-mix(in srgb,var(--brand) 18%,transparent)}
.product-card__media{position:relative;aspect-ratio:1/1;background:var(--wash);overflow:hidden}
.product-card__placeholder,.product-card--placeholder{aspect-ratio:1/1;background:linear-gradient(135deg,var(--wash),var(--wash-2))}
.product-card__body{padding:14px 16px 16px;display:flex;flex-direction:column;gap:5px}
.product-card__title{font-weight:600;font-size:.95rem}
.product-card__price{font-weight:800;color:var(--brand)}
.badge{position:absolute;top:12px;left:12px;padding:5px 12px;border-radius:999px;font-size:.72rem;font-weight:800}
.badge--soldout{background:var(--ink);color:var(--bg)}
.badge--sale{background:var(--accent);color:#fff;left:auto;right:12px}
.price--sale .price__was{color:var(--muted);margin-right:8px;font-weight:500}

/* Product page */
.product{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
@media (max-width:820px){.product{grid-template-columns:1fr;gap:32px}}
.product__media img{border:2px solid var(--wash)}
.product__title{font-size:clamp(1.7rem,3vw,2.5rem);letter-spacing:-.02em}
.product__price{font-size:1.5rem;font-weight:800;color:var(--brand);margin:14px 0 26px}
.product__options{display:flex;flex-wrap:wrap;gap:16px;margin-bottom:22px}
.product__option{display:flex;flex-direction:column;gap:7px;font-size:.86rem;font-weight:700}
.product__option select{padding:.65rem .85rem;background:var(--bg);border:2px solid var(--wash);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body);font-weight:500}
.product__option select:focus-visible{outline:2px solid var(--brand);outline-offset:1px}
.product__description{margin-top:28px;padding:22px;background:var(--wash);border-radius:var(--radius)}
.product__media-placeholder{aspect-ratio:1/1;background:linear-gradient(135deg,var(--wash),var(--wash-2))}

/* Value props */
.value-prop{position:relative;padding:30px 26px;background:var(--wash);border-radius:var(--radius)}
.value-prop:nth-child(2){background:var(--wash-2)}
.value-prop__dot{display:block;width:36px;height:36px;border-radius:50%;background:var(--brand);margin-bottom:16px}
.value-prop:nth-child(2) .value-prop__dot{background:var(--accent)}
.value-prop__title{font-size:1.08rem;font-weight:700;margin-bottom:6px}

/* Cart */
.cart-line{display:grid;grid-template-columns:80px 1fr auto auto;gap:18px;align-items:center;padding:18px 0;border-bottom:2px solid var(--wash)}
.cart-line img{border-radius:calc(var(--radius) / 2)}
.cart-line__title{font-weight:600}
.cart-line__qty{width:68px;padding:.55rem;background:var(--bg);border:2px solid var(--wash);border-radius:999px;text-align:center;color:var(--ink);font-family:var(--font-body);font-weight:600}
.cart-footer{display:flex;flex-wrap:wrap;justify-content:space-between;gap:18px;align-items:center;padding-top:24px}
.cart-subtotal{display:flex;align-items:baseline;gap:12px;font-weight:600}
.cart-subtotal strong{font-size:1.5rem;font-weight:800;color:var(--brand)}
.cart-actions{display:flex;gap:12px}

/* Collections */
.collection-card{position:relative;display:block;overflow:hidden;border:2px solid var(--wash);transition:transform .2s cubic-bezier(.34,1.56,.64,1),border-color .2s ease}
.collection-card:hover{transform:translateY(-4px);border-color:var(--accent)}
.collection-card__title{position:absolute;left:14px;bottom:14px;background:var(--bg);padding:7px 15px;border-radius:999px;font-weight:700;font-size:.9rem}
.collection-head{margin-bottom:28px}

/* Misc */
.rte a{color:var(--brand);text-decoration:underline;text-underline-offset:3px}
.pagination{display:flex;gap:8px;justify-content:center;margin-top:40px;font-weight:700}
.pagination a,.pagination .is-current{padding:6px 14px;border-radius:999px}
.pagination a:hover{background:var(--wash)}
.pagination .is-current{background:var(--brand);color:#fff}
.search-form{display:flex;gap:12px;margin:20px 0 32px}
.search-form input{flex:1;padding:.85rem 1.2rem;background:var(--bg);border:2px solid var(--wash);border-radius:999px;color:var(--ink);font-family:var(--font-body)}
.search-form input::placeholder{color:var(--muted)}
.search-form input:focus-visible{outline:2px solid var(--brand);outline-offset:1px}
:focus-visible{outline:2px solid var(--brand);outline-offset:2px}

/* Footer */
.site-footer{margin-top:56px;padding:48px 0 28px;background:var(--wash);border-top:2px solid var(--wash-2)}
.site-footer__inner{display:flex;flex-wrap:wrap;justify-content:space-between;gap:26px}
.site-footer__name{font-family:var(--font-heading);font-weight:700;font-size:1.15rem;margin:0 0 6px;color:var(--brand)}
.site-footer__nav{display:flex;flex-direction:column;gap:10px;font-size:.92rem}
.site-footer__nav a:hover{color:var(--brand)}
.site-footer__legal{margin-top:28px;font-size:.85rem}

@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

